const TR: Record<Exclude<Lang, "it">, Dict> = {
  en: EN, fr: FR, es: ES, ar: AR, hu: HU, de: DE, ro: RO, pl: PL, bg: BG,
  ru: RU, kk: KK, af: AF, pt: PT, ms: MS, id: ID, zh: ZH, vi: VI,
};

type Ctx = {
  lang: Lang; setLang: (l: Lang) => void; dir: "ltr" | "rtl"; locale: string;
  t: (s: string, vars?: Record<string, string | number>) => string;
  fmt: (n: number, opts?: Intl.NumberFormatOptions) => string;
  fmtDate: (iso: string) => string;
};
const I18nCtx = createContext<Ctx | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>("it");
  useEffect(() => {
    try {
      const saved = window.localStorage.getItem("argus-total-lang") as Lang | null;
      if (saved && LANGS.some((l) => l.code === saved)) setLang(saved);
    } catch { /* SSR/no-storage */ }
  }, []);
  // Recupero automatico dopo un nuovo deploy: se una scheda vecchia prova a
  // caricare un chunk non più presente sul server (ChunkLoadError), ricarico la
  // pagina UNA volta per prendere i file aggiornati (niente loop grazie al flag).
  useEffect(() => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const onErr = (e: any) => {
      const name = String(e?.reason?.name || e?.error?.name || "");
      const msg = String(e?.reason?.message || e?.message || "");
      if (name === "ChunkLoadError" || /Loading chunk [\w-]+ failed|ChunkLoadError|Loading CSS chunk/i.test(msg)) {
        try {
          if (!sessionStorage.getItem("argus-chunk-reload")) {
            sessionStorage.setItem("argus-chunk-reload", "1");
            window.location.reload();
          }
        } catch { window.location.reload(); }
      }
    };
    window.addEventListener("error", onErr);
    window.addEventListener("unhandledrejection", onErr);
    // se la pagina resta stabile qualche secondo, azzera il flag così un futuro
    // deploy potrà di nuovo attivare il ricaricamento
    const tmo = setTimeout(() => { try { sessionStorage.removeItem("argus-chunk-reload"); } catch { /* */ } }, 6000);
    return () => { window.removeEventListener("error", onErr); window.removeEventListener("unhandledrejection", onErr); clearTimeout(tmo); };
  }, []);
  // aggiorna lingua e direzione del documento (RTL per l'arabo)
  useEffect(() => {
    if (typeof document !== "undefined") {
      document.documentElement.lang = lang;
      document.documentElement.dir = RTL_LANGS.includes(lang) ? "rtl" : "ltr";
    }
  }, [lang]);
  const set = (l: Lang) => {
    setLang(l);
    try { window.localStorage.setItem("argus-total-lang", l); } catch { /* */ }
  };
  const t = (s: string, vars?: Record<string, string | number>) => {
    let out = lang === "it" ? s : (TR[lang]?.[s] ?? s);
    if (vars) for (const [k, v] of Object.entries(vars)) out = out.replaceAll(`{${k}}`, String(v));
    return out;
  };
  const dir: "ltr" | "rtl" = RTL_LANGS.includes(lang) ? "rtl" : "ltr";
  const locale = LOCALES[lang] || "en-US";
  const fmt = (n: number, opts?: Intl.NumberFormatOptions) => {
    // useGrouping:"always" forza il separatore delle migliaia anche sui numeri
    // a 4 cifre: alcune lingue (es. it-IT) altrimenti raggruppano solo da 5.
    try { return new Intl.NumberFormat(locale, { useGrouping: "always", ...opts }).format(n); }
    catch { return String(n); }
  };
  const fmtDate = (iso: string) => {
    try { return new Date(iso + "T00:00:00").toLocaleDateString(locale); }
    catch { return iso; }
  };
  return <I18nCtx.Provider value={{ lang, setLang: set, dir, locale, t, fmt, fmtDate }}>{children}</I18nCtx.Provider>;
}

// Traduttore per una lingua qualunque (es. la lingua della stampa, diversa da
// quella dell'interfaccia): stessa logica di t() e fmt() del provider.
export function translatorFor(lang: Lang): { t: (s: string, vars?: Record<string, string | number>) => string; fmt: (n: number, opts?: Intl.NumberFormatOptions) => string } {
  const locale = LOCALES[lang] || "en-US";
  return {
    t: (s, vars) => {
      let out = lang === "it" ? s : (TR[lang as Exclude<Lang, "it">]?.[s] ?? s);
      if (vars) for (const [k, v] of Object.entries(vars)) out = out.replaceAll(`{${k}}`, String(v));
      return out;
    },
    fmt: (n, opts) => { try { return new Intl.NumberFormat(locale, { useGrouping: "always", ...opts }).format(n); } catch { return String(n); } },
  };
}

// Messaggi di errore che arrivano dal server (in italiano): si traduce il testo
// intero; se non c'è, il prefisso «Errore …:» e il resto separatamente.
export function translateError(t: (k: string) => string, msg: string): string {
  const m = (msg || "").trim();
  if (!m) return m;
  const whole = t(m);
  if (whole !== m) return whole;
  const i = m.indexOf(": ");
  if (i > 0) {
    const head = m.slice(0, i), rest = m.slice(i + 2);
    const th = t(head);
    if (th !== head) return `${th}: ${translateError(t, rest)}`;
  }
  return m;
}

export function useI18n(): Ctx {
  const c = useContext(I18nCtx);
  if (!c) throw new Error("useI18n deve stare dentro <I18nProvider>");
  return c;
}
